import { readFileSync } from "node:fs";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { EngineError } from "@nitro-forge/ignition";
import { CliHost } from "@nitro-forge/ignition/cli";
import { FolioDocument, type FolioFormField } from "../src/index";

// Fixture generated by `cargo run -p folio-engine --example
// gen_form_fixture -- packages/folio/tests/fixtures/forms.pdf`: one page
// with merged Tx/Btn/Ch/Sig widgets plus a two-widget radio group.
const fixtureBytes = () =>
  new Uint8Array(
    readFileSync(join(import.meta.dirname, "fixtures/forms.pdf")),
  );

let host: CliHost;
beforeAll(() => {
  host = new CliHost();
});
afterAll(async () => {
  await host.dispose();
});

const byName = (fields: FolioFormField[], name: string) =>
  fields.find((f) => f.name === name);

describe("folio form fields e2e (real Rust via nf-cli)", () => {
  it("lists every field kind from a real PDF", async () => {
    const doc = await FolioDocument.openPdf(host, fixtureBytes());
    const { fields } = (await doc.listFormFields()).data;
    // name, agree, 2x choice, pick, signature = 6 rows
    expect(fields).toHaveLength(6);
    expect(byName(fields, "name")).toMatchObject({
      page: 0, ft: "Tx", v: "old", ff: 0, signature: false,
    });
    expect(byName(fields, "agree")).toMatchObject({ ft: "Btn", v: "Yes" });
    expect(fields.filter((f) => f.name === "choice")).toHaveLength(2);
    expect(byName(fields, "pick")).toMatchObject({ ft: "Ch", v: "a" });
    expect(byName(fields, "signature")).toMatchObject({
      ft: "Sig", signature: true,
    });
    for (const f of fields) {
      expect(f.rect).not.toBeNull();
      expect(typeof f.annot).toBe("number");
    }
    const described = (await doc.describe<Record<string, unknown>>()).data;
    expect(described.has_forms).toBe(true);
    await doc.close();
  });

  it("fills text and choice fields, persists through save/reopen", async () => {
    const doc = await FolioDocument.openPdf(host, fixtureBytes());
    await doc.fillFormField(0, { field: "name" }, "Ada Lovelace");
    await doc.fillFormField(0, { field: "pick" }, "b");
    let fields = (await doc.listFormFields()).data.fields;
    expect(byName(fields, "name")?.v).toBe("Ada Lovelace");
    expect(byName(fields, "pick")?.v).toBe("b");

    const { bytes } = await doc.savePdf();
    const reopened = await FolioDocument.openPdf(host, bytes);
    fields = (await reopened.listFormFields()).data.fields;
    expect(byName(fields, "name")?.v).toBe("Ada Lovelace");
    expect(byName(fields, "pick")?.v).toBe("b");
    await reopened.close();
    await doc.close();
  });

  it("fills checkboxes and radio groups with /AS state sync", async () => {
    const doc = await FolioDocument.openPdf(host, fixtureBytes());
    // Checkbox off/on via state names.
    await doc.fillFormField(0, { field: "agree" }, "Off");
    let fields = (await doc.listFormFields()).data.fields;
    expect(byName(fields, "agree")?.v).toBe("Off");
    await doc.fillFormField(0, { field: "agree" }, "Yes");
    fields = (await doc.listFormFields()).data.fields;
    expect(byName(fields, "agree")?.v).toBe("Yes");

    // Radio: ambiguous by name, target by annot id.
    const radios = fields.filter((f) => f.name === "choice");
    await expect(
      doc.fillFormField(0, { field: "choice" }, "B"),
    ).rejects.toBeInstanceOf(EngineError);
    await doc.fillFormField(0, { annot: radios[1]!.annot! }, "B");
    fields = (await doc.listFormFields()).data.fields;
    expect(fields.filter((f) => f.name === "choice").every((f) => f.v === "B")).toBe(true);
    await doc.close();
  });

  it("rejects signature fields and reports undo correctly", async () => {
    const doc = await FolioDocument.openPdf(host, fixtureBytes());
    await expect(
      doc.fillFormField(0, { field: "signature" }, "forged"),
    ).rejects.toBeInstanceOf(EngineError);
    const before = (await doc.listFormFields()).data.fields;
    expect(byName(before, "signature")?.v).toBeNull();

    await doc.fillFormField(0, { field: "name" }, "before-undo");
    expect(await doc.undo()).toBe(true);
    const after = (await doc.listFormFields()).data.fields;
    expect(byName(after, "name")?.v).toBe("old");
    expect(await doc.redo()).toBe(true);
    const redone = (await doc.listFormFields()).data.fields;
    expect(byName(redone, "name")?.v).toBe("before-undo");
    await doc.close();
  });

  it("rejects form ops on encrypted documents", async () => {
    const doc = await FolioDocument.openPdf(host, fixtureBytes());
    await doc.encrypt({ password: "pw" });
    await expect(doc.listFormFields()).rejects.toBeInstanceOf(EngineError);
    await expect(
      doc.fillFormField(0, { field: "name" }, "x"),
    ).rejects.toBeInstanceOf(EngineError);
    await doc.close();
  });
});
